'use client';
import React from 'react';
import type { Exploit } from '@/lib/data';

interface AdminStatsBarProps {
  exploits: Exploit[];
}

export default function AdminStatsBar({ exploits }: AdminStatsBarProps) {
  const published = exploits.filter(e => e.status === 'published').length;
  const featured = exploits.filter(e => e.featured).length;
  const draft = exploits.filter(e => e.status === 'draft').length;
  const archived = exploits.filter(e => e.status === 'archived').length;
  const totalViews = exploits.reduce((s, e) => s + e.views, 0);

  const stats = [
    { label: 'Total Exploits', value: exploits.length, color: '#00ff41', sub: 'all entries' },
    { label: 'Published', value: published, color: '#00ff41', sub: `${Math.round((published / exploits.length) * 100)}% of total` },
    { label: 'Featured', value: featured, color: '#ff6b35', sub: 'admin picks' },
    { label: 'Drafts', value: draft, color: '#f59e0b', sub: 'pending review' },
    { label: 'Archived', value: archived, color: '#1a4d2e', sub: 'hidden from public' },
    { label: 'Total Views', value: (totalViews / 1000).toFixed(0) + 'k', color: '#00ffff', sub: 'all time' },
  ];

  return (
    <div data-component-id="src/app/admin-content-management/components/AdminStatsBar.tsx:26:4" data-component-path="src/app/admin-content-management/components/AdminStatsBar.tsx" data-component-line="26" data-component-end-line="37" data-component-file="AdminStatsBar.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22grid%20grid-cols-2%20md%3Agrid-cols-3%20xl%3Agrid-cols-6%20gap-3%22%7D" className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-3">
      {stats.map((stat) => (
        <div data-component-id="src/app/admin-content-management/components/AdminStatsBar.tsx:28:8" data-component-path="src/app/admin-content-management/components/AdminStatsBar.tsx" data-component-line="28" data-component-end-line="35" data-component-file="AdminStatsBar.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22bg-%5B%230f0f0f%5D%20border%20border-%5B%23003d15%5D%20rounded%20p-3%20hover%3Aborder-%5B%2300ff41%5D%20transition-all%20duration-200%22%7D"
          key={`admin-stat-${stat.label}`}
          className="bg-[#0f0f0f] border border-[#003d15] rounded p-3 hover:border-[#00ff41] transition-all duration-200"
        >
          <div data-component-id="src/app/admin-content-management/components/AdminStatsBar.tsx:32:10" data-component-path="src/app/admin-content-management/components/AdminStatsBar.tsx" data-component-line="32" data-component-end-line="32" data-component-file="AdminStatsBar.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22font-mono%20text-%5B10px%5D%20text-%5B%2300802a%5D%20uppercase%20tracking-wider%20mb-1%22%7D" className="font-mono text-[10px] text-[#00802a] uppercase tracking-wider mb-1">{stat.label}</div>
          <div data-component-id="src/app/admin-content-management/components/AdminStatsBar.tsx:33:10" data-component-path="src/app/admin-content-management/components/AdminStatsBar.tsx" data-component-line="33" data-component-end-line="33" data-component-file="AdminStatsBar.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22font-mono%20text-2xl%20font-bold%20text-tabular%22%7D" className="font-mono text-2xl font-bold text-tabular" style={{ color: stat.color }}>{stat.value}</div>
          <div data-component-id="src/app/admin-content-management/components/AdminStatsBar.tsx:34:10" data-component-path="src/app/admin-content-management/components/AdminStatsBar.tsx" data-component-line="34" data-component-end-line="34" data-component-file="AdminStatsBar.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22font-mono%20text-%5B10px%5D%20text-%5B%231a4d2e%5D%20mt-0.5%22%7D" className="font-mono text-[10px] text-[#1a4d2e] mt-0.5">{stat.sub}</div>
        </div>
      ))}
    </div>
  );
}