'use client';
import React, { useState, useMemo } from 'react';
import { EXPLOITS as INITIAL_EXPLOITS, CATEGORIES, type Exploit, type CategorySlug, type ExploitStatus } from '@/lib/data';
import AdminStatsBar from './AdminStatsBar';
import ExploitTable from './ExploitTable';
import ExploitFormModal from './ExploitFormModal';
import DeleteConfirmModal from './DeleteConfirmModal';
import CategoryPanel from './CategoryPanel';
import { toast } from 'sonner';

export type AdminTab = 'content' | 'categories';

export default function AdminContentClient() {
  const [exploits, setExploits] = useState<Exploit[]>(INITIAL_EXPLOITS);
  const [activeTab, setActiveTab] = useState<AdminTab>('content');
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<CategorySlug | 'all'>('all');
  const [statusFilter, setStatusFilter] = useState<ExploitStatus | 'all'>('all');
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [sortCol, setSortCol] = useState<string>('views');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('desc');
  const [editingExploit, setEditingExploit] = useState<Exploit | null>(null);
  const [isCreating, setIsCreating] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [bulkDeleteConfirm, setBulkDeleteConfirm] = useState(false);

  const filteredExploits = useMemo(() => {
    let results = [...exploits];
    if (categoryFilter !== 'all') results = results.filter(e => e.category === categoryFilter);
    if (statusFilter !== 'all') results = results.filter(e => e.status === statusFilter);
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      results = results.filter(e =>
        e.title.toLowerCase().includes(q) ||
        e.description.toLowerCase().includes(q) ||
        e.id.includes(q) ||
        e.tags.some(t => t.includes(q))
      );
    }
    results.sort((a, b) => {
      let av: string | number = '';
      let bv: string | number = '';
      if (sortCol === 'views') { av = a.views; bv = b.views; }
      else if (sortCol === 'title') { av = a.title; bv = b.title; }
      else if (sortCol === 'createdAt') { av = a.createdAt; bv = b.createdAt; }
      else if (sortCol === 'updatedAt') { av = a.updatedAt; bv = b.updatedAt; }
      else if (sortCol === 'difficulty') { av = a.difficulty; bv = b.difficulty; }
      if (typeof av === 'number' && typeof bv === 'number') {
        return sortDir === 'asc' ? av - bv : bv - av;
      }
      return sortDir === 'asc' ? String(av).localeCompare(String(bv)) : String(bv).localeCompare(String(av));
    });
    return results;
  }, [exploits, categoryFilter, statusFilter, searchQuery, sortCol, sortDir]);

  const handleSort = (col: string) => {
    if (sortCol === col) setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    else { setSortCol(col); setSortDir('desc'); }
  };

  const handleStatusChange = (id: string, status: ExploitStatus) => {
    setExploits(prev => prev.map(e => e.id === id ? { ...e, status, updatedAt: new Date().toISOString().split('T')[0] } : e));
    toast.success(`Status updated to ${status}`);
    // Backend: PATCH /api/exploits/:id { status }
  };

  const handleToggleFeatured = (id: string) => {
    setExploits(prev => prev.map(e => e.id === id ? { ...e, featured: !e.featured } : e));
    const exploit = exploits.find(e => e.id === id);
    toast.success(exploit?.featured ? 'Removed from featured' : 'Added to featured');
    // Backend: PATCH /api/exploits/:id { featured }
  };

  const handleSave = (data: Partial<Exploit>) => {
    if (editingExploit) {
      setExploits(prev => prev.map(e => e.id === editingExploit.id ? { ...e, ...data, updatedAt: new Date().toISOString().split('T')[0] } : e));
      toast.success('Exploit updated successfully');
      // Backend: PUT /api/exploits/:id { ...data }
    } else {
      const newExploit: Exploit = {
        id: `exploit-${String(Date.now()).slice(-6)}`,
        title: data.title || '',
        description: data.description || '',
        category: data.category || 'browser-hacks',
        tags: data.tags || [],
        difficulty: data.difficulty || 'easy',
        status: data.status || 'draft',
        views: 0,
        code: data.code,
        url: data.url,
        instructions: data.instructions || '',
        addedBy: 'admin',
        createdAt: new Date().toISOString().split('T')[0],
        updatedAt: new Date().toISOString().split('T')[0],
        featured: false,
        works_on: data.works_on || ['Chrome'],
      };
      setExploits(prev => [newExploit, ...prev]);
      toast.success('New exploit created');
      // Backend: POST /api/exploits { ...data }
    }
    setEditingExploit(null);
    setIsCreating(false);
  };

  const handleDelete = (id: string) => {
    setExploits(prev => prev.filter(e => e.id !== id));
    setDeletingId(null);
    toast.success('Exploit deleted');
    // Backend: DELETE /api/exploits/:id
  };

  const handleBulkDelete = () => {
    setExploits(prev => prev.filter(e => !selectedIds.has(e.id)));
    toast.success(`${selectedIds.size} exploits deleted`);
    setSelectedIds(new Set());
    setBulkDeleteConfirm(false);
    // Backend: DELETE /api/exploits/bulk { ids: [...selectedIds] }
  };

  const handleBulkStatusChange = (status: ExploitStatus) => {
    setExploits(prev => prev.map(e => selectedIds.has(e.id) ? { ...e, status } : e));
    toast.success(`${selectedIds.size} exploits set to ${status}`);
    setSelectedIds(new Set());
    // Backend: PATCH /api/exploits/bulk { ids: [...selectedIds], status }
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === filteredExploits.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(filteredExploits.map(e => e.id)));
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  return (
    <div data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:145:4" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="145" data-component-end-line="236" data-component-file="AdminContentClient.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22space-y-6%22%7D" className="space-y-6">
      {/* Page header */}
      <div data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:147:6" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="147" data-component-end-line="161" data-component-file="AdminContentClient.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex%20items-center%20justify-between%22%7D" className="flex items-center justify-between">
        <div data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:148:8" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="148" data-component-end-line="153" data-component-file="AdminContentClient.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%7D">
          <h1 data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:149:10" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="149" data-component-end-line="149" data-component-file="AdminContentClient.tsx" data-component-name="h1" data-component-content="%7B%22elementName%22%3A%22h1%22%2C%22className%22%3A%22font-mono%20text-xl%20font-bold%20text-%5B%2300ff41%5D%22%2C%22textContent%22%3A%22Content%20Management%22%7D" className="font-mono text-xl font-bold text-[#00ff41]">Content Management</h1>
          <p data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:150:10" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="150" data-component-end-line="152" data-component-file="AdminContentClient.tsx" data-component-name="p" data-component-content="%7B%22elementName%22%3A%22p%22%2C%22className%22%3A%22font-mono%20text-xs%20text-%5B%2300802a%5D%20mt-0.5%22%2C%22textContent%22%3A%22Manage%20all%20exploits%2C%20bookmarklets%2C%20and%20site%20listings%22%7D" className="font-mono text-xs text-[#00802a] mt-0.5">
            Manage all exploits, bookmarklets, and site listings
          </p>
        </div>
        <button data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:154:8" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="154" data-component-end-line="160" data-component-file="AdminContentClient.tsx" data-component-name="button" data-component-content="%7B%22elementName%22%3A%22button%22%2C%22className%22%3A%22flex%20items-center%20gap-2%20font-mono%20text-xs%20font-bold%20px-4%20py-2%20bg-%5B%23001a08%5D%20border%20border-%5B%2300ff41%5D%20text-%5B%2300ff41%5D%20rounded%20hover%3Abg-%5B%23003d15%5D%20hover%3Ashadow-terminal%20transition-all%20duration-150%20active%3Ascale-95%22%2C%22textContent%22%3A%22New%20Exploit%22%7D"
          onClick={() => setIsCreating(true)}
          className="flex items-center gap-2 font-mono text-xs font-bold px-4 py-2 bg-[#001a08] border border-[#00ff41] text-[#00ff41] rounded hover:bg-[#003d15] hover:shadow-terminal transition-all duration-150 active:scale-95"
        >
          <span data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:158:10" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="158" data-component-end-line="158" data-component-file="AdminContentClient.tsx" data-component-name="span" data-component-content="%7B%22elementName%22%3A%22span%22%2C%22className%22%3A%22text-base%20leading-none%22%2C%22textContent%22%3A%22%2B%22%7D" className="text-base leading-none">+</span>
          New Exploit
        </button>
      </div>

      {/* Stats bar */}
      <AdminStatsBar data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:164:6" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="164" data-component-end-line="164" data-component-file="AdminContentClient.tsx" data-component-name="AdminStatsBar" data-component-content="%7B%22elementName%22%3A%22AdminStatsBar%22%7D" exploits={exploits} />

      {/* Tabs */}
      <div data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:167:6" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="167" data-component-end-line="181" data-component-file="AdminContentClient.tsx" data-component-name="div" data-component-content="%7B%22elementName%22%3A%22div%22%2C%22className%22%3A%22flex%20gap-1%20border-b%20border-%5B%23003d15%5D%20pb-0%22%7D" className="flex gap-1 border-b border-[#003d15] pb-0">
        {(['content', 'categories'] as AdminTab[]).map(tab => (
          <button data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:169:10" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="169" data-component-end-line="179" data-component-file="AdminContentClient.tsx" data-component-name="button" data-component-content="%7B%22elementName%22%3A%22button%22%7D"
            key={`tab-${tab}`}
            onClick={() => setActiveTab(tab)}
            className={`font-mono text-xs font-medium px-4 py-2 rounded-t border border-b-0 transition-all duration-150
              ${activeTab === tab
                ? 'bg-[#0f0f0f] border-[#003d15] text-[#00ff41] border-b-[#0f0f0f]'
                : 'border-transparent text-[#00802a] hover:text-[#00ff41]'
              }`}
          >
            {tab === 'content' ? `Exploits (${exploits.length})` : 'Categories'}
          </button>
        ))}
      </div>

      {/* Tab content */}
      {activeTab === 'content' ? (
        <ExploitTable data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:185:8" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="185" data-component-end-line="206" data-component-file="AdminContentClient.tsx" data-component-name="ExploitTable" data-component-content="%7B%22elementName%22%3A%22ExploitTable%22%7D"
          exploits={filteredExploits}
          allExploits={exploits}
          searchQuery={searchQuery}
          onSearchChange={setSearchQuery}
          categoryFilter={categoryFilter}
          onCategoryFilterChange={setCategoryFilter}
          statusFilter={statusFilter}
          onStatusFilterChange={setStatusFilter}
          selectedIds={selectedIds}
          onToggleSelect={toggleSelect}
          onToggleSelectAll={toggleSelectAll}
          sortCol={sortCol}
          sortDir={sortDir}
          onSort={handleSort}
          onEdit={setEditingExploit}
          onDelete={setDeletingId}
          onStatusChange={handleStatusChange}
          onToggleFeatured={handleToggleFeatured}
          onBulkDelete={() => setBulkDeleteConfirm(true)}
          onBulkStatusChange={handleBulkStatusChange}
        />
      ) : (
        <CategoryPanel data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:208:8" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="208" data-component-end-line="208" data-component-file="AdminContentClient.tsx" data-component-name="CategoryPanel" data-component-content="%7B%22elementName%22%3A%22CategoryPanel%22%7D" categories={CATEGORIES} exploits={exploits} />
      )}

      {/* Modals */}
      {(isCreating || editingExploit) && (
        <ExploitFormModal data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:213:8" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="213" data-component-end-line="217" data-component-file="AdminContentClient.tsx" data-component-name="ExploitFormModal" data-component-content="%7B%22elementName%22%3A%22ExploitFormModal%22%7D"
          exploit={editingExploit}
          onSave={handleSave}
          onClose={() => { setIsCreating(false); setEditingExploit(null); }}
        />
      )}

      {deletingId && (
        <DeleteConfirmModal data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:221:8" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="221" data-component-end-line="225" data-component-file="AdminContentClient.tsx" data-component-name="DeleteConfirmModal" data-component-content="%7B%22elementName%22%3A%22DeleteConfirmModal%22%7D"
          title={exploits.find(e => e.id === deletingId)?.title || ''}
          onConfirm={() => handleDelete(deletingId)}
          onCancel={() => setDeletingId(null)}
        />
      )}

      {bulkDeleteConfirm && (
        <DeleteConfirmModal data-component-id="src/app/admin-content-management/components/AdminContentClient.tsx:229:8" data-component-path="src/app/admin-content-management/components/AdminContentClient.tsx" data-component-line="229" data-component-end-line="234" data-component-file="AdminContentClient.tsx" data-component-name="DeleteConfirmModal" data-component-content="%7B%22elementName%22%3A%22DeleteConfirmModal%22%7D"
          title={`${selectedIds.size} selected exploits`}
          onConfirm={handleBulkDelete}
          onCancel={() => setBulkDeleteConfirm(false)}
          isBulk
        />
      )}
    </div>
  );
}